// STANDARD LOOP (Baseline)

void process_array(int* arr, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        arr[i] *= 2;
    }
}

// MANUAL LOOP UNROLLING (Factor = 4)

void process_unrolled(int* arr, size_t N) {
    size_t i = 0;
    for (; i + 3 < N; i += 4) {
        arr[i]     *= 2;
        arr[i + 1] *= 2;
        arr[i + 2] *= 2;
        arr[i + 3] *= 2;
    }
    // Handle remaining elements (Epilogue)
    for (; i < N; ++i) {
        arr[i] *= 2;
    }
}
